func maxProduct(nums []int) int {
    res, maxP, minP := nums[0], nums[0], nums[0]
    for i := 1; i < len(nums); i++ {
        // 负数翻转最大最小
        if nums[i] < 0 {
            maxP, minP = minP, maxP
        }
        maxP = max(nums[i], maxP*nums[i])
        minP = min(nums[i], minP*nums[i])
        res = max(res, maxP)
    }
    return res
}
